    try {
      await StorageManager.clearAllData();
      dispatch({ type: ActionTypes.CLEAR_ALL_DATA });
    } catch (error) {
      console.error('Error clearing data:', error);
      dispatch({ type: ActionTypes.SET_ERROR, payload: error.message });
    }
  };

