    try {
      dispatch({ type: ActionTypes.SET_LOADING, payload: true });
      await StorageManager.resetToDummyData();
      await loadAllData();
    } catch (error) {
      console.error('Error resetting to dummy data:', error);
      dispatch({ type: ActionTypes.SET_ERROR, payload: error.message });
    }
  };

